<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Student Login Credentials</h1><p>Create a login and give the displayed password securely to the student.</p></div></header>
<?php if($temporaryCredential):?><div class="notice-panel"><strong>Login password (copy now):</strong>&nbsp;<code><?= e($temporaryCredential) ?></code><p>For security, it will not be displayed again after leaving this page.</p></div><?php endif ?>
<section class="module-card"><header class="module-card__header"><div><h2>Create Student Login</h2></div></header><div class="module-card__body"><form method="post" action="<?= url('/admin/students/logins') ?>"><?= csrf_field() ?><div class="module-form-grid module-form-grid--three"><div class="module-field"><label>Student</label><select class="module-select" name="student_id" required><option value="">Select Student</option><?php foreach($accounts as$a):if($a['email'])continue;?><option value="<?= $a['id'] ?>"><?= e($a['display_name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Login Email</label><input class="module-input" type="email" name="email" required></div><div class="module-field"><label>Password</label><input class="module-input" type="text" name="password" minlength="8" autocomplete="new-password" placeholder="Leave blank to generate securely"><small>Minimum 8 characters, or leave blank for an automatic password.</small></div></div><button class="btn btn--primary"><i data-lucide="key-round"></i>Create Login</button></form></div></section>
<section class="module-card"><header class="module-card__header"><div><h2>Student Accounts</h2></div></header><div class="module-card__body"><div class="table-scroll"><table class="data-table"><thead><tr><th>Student</th><th>Email</th><th>Password</th><th>Status</th><th>Change Password</th><th>Access</th></tr></thead><tbody><?php foreach($accounts as$a):?><tr><td><?= e($a['display_name']) ?></td><td><?= e($a['email']?:'Not created') ?></td><td><code><?= e($a['visible_password']??($a['email']?'Reset required':'—')) ?></code></td><td><?= e($a['status']?:'—') ?></td><td><?php if($a['email']):?><form class="credential-change-form" method="post" action="<?= url('/admin/students/logins') ?>"><?= csrf_field() ?><input type="hidden" name="student_id" value="<?= $a['id'] ?>"><input type="hidden" name="email" value="<?= e($a['email']) ?>"><input class="module-input" type="text" name="password" minlength="8" required placeholder="New password"><button class="btn btn--secondary" type="submit">Change</button></form><?php else:?>—<?php endif ?></td><td><?php if(can('*')&&!empty($a['user_id'])&&$a['status']==='active'):?><form method="post" action="<?=e(url('/admin/impersonate/'.(int)$a['user_id']))?>"><?=csrf_field()?><button class="btn btn--secondary" type="submit"><i data-lucide="eye"></i>View as student</button></form><?php else:?>—<?php endif?></td></tr><?php endforeach ?></tbody></table></div></div></section></div></div></main>

